Bash(node -e "
const colors = [
  ['#2E7D32', 'Primary'],
  ['#6AAF4A', 'Fresh Green'],
  ['#C4451A', 'Accent'],
  ['#EEF5E9', 'Background'],
  ['#1B2E1A', 'Dark'],
  ['#F5F9F2', 'Light'],
  ['#5A6B55', 'Text Muted'],
  ['#D5DBC8', 'Border'],
];

for \(const [hex, label] of colors\) {
  let r = parseInt\(hex.slice\(1,3\), 16\) / 255;
  let g = parseInt\(hex.slice\(3,5\), 16\) / 255;
  let b = parseInt\(hex.slice\(5,7\), 16\) / 255;
  let max = Math.max\(r, g, b\), min = Math.min\(r, g, b\);
  let h, s, l = \(max + min\) / 2;
  let d = max - min;
  if \(d === 0\) { h = 0; s = 0; }
  else {
    s = l > 0.5 ? d / \(2 - max - min\) : d / \(max + min\);
    if \(max === r\) h = \(\(g - b\) / d + \(g < b ? 6 : 0\)\) / 6;
    else if \(max === g\) h = \(\(b - r\) / d + 2\) / 6;
    else h = \(\(r - g\) / d + 4\) / 6;
  }
  console.log\(label + ': ' + Math.round\(h * 360\) + ' ' + Math.round\(s * 100\) + '% ' + Math.round\(l * 100\) + '%'\);
}
")

